# Generated by `shiny theme new` from shiny-city.jpg
# Base scheme: Nord — https://github.com/mbadolato/iTerm2-Color-Schemes (via Ghostty)
# Edit freely; `shiny theme set <name>` re-applies.
THEME_BASE="Nord"
GHOSTTY_THEME="Nord"   # built-in: ghostty +list-themes
ACCENT_PRESET=4                    # macOS accent: -1 graphite 0 red 1 orange 2 yellow 3 green 4 blue 5 purple 6 pink
WALLPAPER="wallpaper.jpg"

BG="#2E3440"         # window background
BG_DARK="#272C36"    # frames, omnibox
SURFACE="#3B4252"    # borders, dividers, inactive window border
SELECTION="#434C5E"  # selected rows, text selection
MUTED="#4C566A"      # shortcuts, scrollbar
COMMENT="#616E88"    # subtext, inactive tabs
FG="#D8DEE9"         # primary text
FG_DIM="#E5E9F0"     # secondary text
ACCENT="#81A1C1"     # primary accent: focus border, icons, links, text highlight, icon tint
ACCENT2="#B48EAD"    # secondary accent: cursor, shortcuts, search selection
